    topic: { en: "Store network / 4G backup", es: "Red de tienda / respaldo 4G" },
    minutes: 15,
    title: { en: "The store loses internet two hours before opening", es: "La tienda se queda sin internet dos horas antes de abrir" },
    guide: GUIDE + "router-4g-la-conexion-de-la-tienda-cae-dos-horas-antes-de-abrir.html",
    machine: WS_MACHINE,
