  const CX_RULES = (fixed) => ["", "Name              : Clinical-W2022_Direct", "DesktopGroupName  : Clinical-W2022", "AllowedConnections: NotViaAG", "IncludedUsers     : {CONTOSO\\GG-Clinic-Pilot" + (fixed ? ", CONTOSO\\GG-Clinic-Ward3" : "") + "}",
    "", "Name              : Clinical-W2022_AG", "DesktopGroupName  : Clinical-W2022", "AllowedConnections: ViaAG", "IncludedUsers     : {CONTOSO\\GG-Clinic-Pilot" + (fixed ? ", CONTOSO\\GG-Clinic-Ward3" : "") + "}", ""];
